<?php
declare(strict_types=1);require_once dirname(__DIR__) . '/bootstrap.php';require_method('GET');$u=current_user();$id=trim((string)($_GET['id']??''));$s=db()->prepare('SELECT public_id id,original_filename filename,status,total_rows totalRows,processed_rows processedRows,imported_rows importedRows,duplicate_rows duplicateRows,failed_rows failedRows,error_message error,created_at createdAt,updated_at updatedAt FROM import_jobs WHERE tenant_id=? AND public_id=?');$s->execute([$u['tenant_id'],$id]);$r=$s->fetch();if(!$r)throw new ApiError(404,'Import job not found.');$r['progress']=(int)$r['totalRows']>0?min(100,round((int)$r['processedRows']*100/(int)$r['totalRows'])):0;respond($r);
